try{
  ClipboardPage Primary = tools.getPrimaryPage();
  ClipboardPage DataJSON = tools.findPage("MyPageSalvage.ClaimData.Lelang");
  ClipboardPage SETJSON = tools.findPage("MyPageSalvage.ClaimData");
  String ClaimNumber = DataJSON.getProperty(".ClaimNumber").toString();
  String BusinessCode = DataJSON.getProperty(".BusinessCode").toString();
  String CoverageName = DataJSON.getProperty(".CoverageName").toString();
  String Currency = DataJSON.getProperty(".Currency").toString();
  String InsuredName = DataJSON.getProperty(".InsuredName").toString();
  String InsuredPrice = DataJSON.getProperty(".InsuredPrice").toString();
  String MinimumPrice = DataJSON.getProperty(".MinimumPrice").toString();
  String ObjectName = DataJSON.getProperty(".ObjectName").toString();
  String pyCompany = DataJSON.getProperty(".pyCompany").toString();
  String Remark = DataJSON.getProperty(".Remark").toString();
  String SalvageDate = DataJSON.getProperty(".SalvageDate").toString();
  String SalvageLocation = DataJSON.getProperty(".SalvageLocation").toString();
  String SalvagePrice = DataJSON.getProperty(".SalvagePrice").toString();
  String SalvageStatus = DataJSON.getProperty(".SalvageStatus").toString();
  String SalvageType = DataJSON.getProperty(".SalvageType").toString();
  String Coas = DataJSON.getProperty(".Coas").toString();
  String Insured = DataJSON.getProperty(".Insured").toString();


  String Renew_json = "{\"Lelang\":{"
    +"\"BusinessCode\":\""+BusinessCode+"\","
    +"\"ClaimNumber\":\""+ClaimNumber+"\","
    +"\"CoverageName\":\""+CoverageName+"\","
    +"\"Currency\":\""+Currency+"\","
    +"\"InsuredName\":\""+InsuredName+"\","
    +"\"InsuredPrice\":\""+InsuredPrice+"\","
    +"\"MinimumPrice\":\""+MinimumPrice+"\","
    +"\"ObjectName\":\""+ObjectName+"\","
    +"\"pyCompany\":\""+pyCompany+"\","
    +"\"Remark\":\""+Remark+"\","
    +"\"SalvageDate\":\""+SalvageDate+"\","
    +"\"SalvageLocation\":\""+SalvageLocation+"\","
    +"\"SalvagePrice\":\""+SalvagePrice+"\","
    +"\"SalvageStatus\":\""+SalvageStatus+"\","
    +"\"SalvageType\":\""+SalvageType+"\","
    +"\"Coas\":\""+Coas+"\","
    +"\"Insured\":\""+Insured+"\""+
    "}}";

  SETJSON.getProperty(".AlasanKlaim").setValue(Renew_json);
} catch(Exception e){
  oLog.error("ReloadSection:Expection : "+e.getMessage());
}

try{
  ClipboardPage Primary = tools.getPrimaryPage();
  ClipboardPage DataJSON = tools.findPage("PageSalvage.ClaimData");
  ClipboardProperty DataJSONList  = DataJSON.getProperty(".NoteKasir");
  String data_js = DataJSONList.toString();
  DataJSON.adoptJSONObject(data_js);
  ClipboardPage Isi_Respond = tools.findPage("PageSalvage.ClaimData.Response");
  ClipboardProperty Property_res = Isi_Respond.getProperty(".pyStatusMessage");
  ClipboardProperty Property_message = Isi_Respond.getProperty(".pyMessage");
  ClipboardPage PageRespondStatus_p = tools.findPage("PageRespondStatus");
  String Info_status = Property_res.toString();
  PageRespondStatus_p.getProperty(".NoteKasir").setValue(Info_status);
  Info_status = Property_message.toString();
  PageRespondStatus_p.getProperty(".AlasanTerlambat").setValue(Info_status);
} catch(Exception e){
  oLog.error("ReloadSection:Expection : "+e.getMessage());
}
